/** One character. It rolls in only if it mounted after the first render, i.e. because the value changed. */
function RollChar({ c, animate, delay }: { c: string; animate: boolean; delay: number }) {
  const [on] = useState(animate);
  return (
    <span className="inline-block whitespace-pre" style={on ? { animation: `kit-co-roll .5s ${CURVE} ${delay}ms both` } : undefined}>
      {c}
    </span>
  );
}

/** Formatted money whose changed characters roll in from the direction the value moved. */
function Money({ value, format, className }: { value: number; format: (n: number) => string; className?: string }) {
  const [prev, setPrev] = useState(value);
  const [dir, setDir] = useState(0);
  if (prev !== value) {
    setDir(value > prev ? 1 : -1);
    setPrev(value);
  }
  const s = format(value);
  const chars = s.split("");
  return (
    <span className={cx("inline-flex overflow-hidden tabular-nums", className)} style={{ ["--kit-co-d" as string]: dir || 1 }}>
      <span className="sr-only">{s}</span>
      <span aria-hidden className="inline-flex">
        {chars.map((c, i) => (
          // Keyed by position from the right, so only characters that changed re-mount and roll.
          <RollChar key={`${chars.length - i}-${c}`} c={c} animate={dir !== 0} delay={(chars.length - i) * 18} />
        ))}
      </span>
    </span>
  );
}

